css:
.terms-container {
    display: flex;
    justify-content: space-between;
    direction: ltr;
    font-family: Arial, sans-serif;
    line-height: 1.5;
    margin: 20px;
  }
  .terms-left, .terms-right {
    width: 48%;
  }
  .terms-left {
    text-align: left;
  }
  .terms-right {
    text-align: right;
    direction: rtl;
  }
  h2 {
    color: #c00;
    margin-bottom: 10px;
  }
  ol {
    margin: 0;
    padding-left: 20px;
  }
  .note {
    color: #c00;
    font-weight: bold;
    margin-top: 10px;
  }
